'use strict';

const semver = require('semver');
const { checkProjectType } = require('./project-type');
const { resolveProjectMajor } = require('./cds-version');
const { checkConsistency } = require('./consistency');

function deriveTarget() {
  try {
    const pkgPath = require.resolve('@sap/cds-dk/package.json');
    return semver.major(require(pkgPath).version);
  } catch {
    return semver.major(require('../../../package.json').version);
  }
}

async function runPreflight(ctx, cds) {
  const { info, error, bold } = require('../../../lib/util/term');

  ctx.target = deriveTarget();
  console.log(`${bold(`Upgrading project to cds ${ctx.target}`)}`);
  console.log();

  const projectType = await checkProjectType(ctx, cds);
  if (!projectType.passed) {
    console.log(`  ${error('✗')} ${projectType.message}`);
    return { ok: false, target: ctx.target, projectMajor: null };
  }
  console.log(`  ${info('✓')} ${projectType.message}`);

  const consistency = await checkConsistency(ctx, cds);
  if (!consistency.ok) return { ok: false, target: ctx.target, projectMajor: null };

  const projectMajor = resolveProjectMajor(ctx, cds);
  ctx.project.major = projectMajor;
  if (projectMajor !== null) {
    // Permissive ranges (e.g. `*`, `latest`, `>=7`) satisfy any target and
    // are not evidence of a lagging major — skip them here too.
    const majors = consistency.occurrences
      .filter(o => !o.permissive && o.cdsMajor !== null)
      .map(o => o.cdsMajor);
    const displayMajor = majors.length > 0 ? Math.min(...majors) : projectMajor;
    console.log(`  ${info('✓')} You are on cds ${displayMajor}`);
  }

  return { ok: true, target: ctx.target, projectMajor };
}

module.exports = { runPreflight };
